const std = @import("std");
const math = std.math;
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;

const Tensor = struct {
    data: []f32,
    shape: []usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, shape: []const usize) !Tensor {
        var total: usize = 1;
        for (shape) |dim| {
            total *= dim;
        }
        const data = try allocator.alloc(f32, total);
        const shape_copy = try allocator.dupe(usize, shape);
        return Tensor{
            .data = data,
            .shape = shape_copy,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
    }

    pub fn view(self: Tensor, new_shape: []const usize) !Tensor {
        var total: usize = 1;
        for (new_shape) |dim| {
            total *= dim;
        }
        const shape_copy = try self.allocator.dupe(usize, new_shape);
        return Tensor{
            .data = self.data,
            .shape = shape_copy,
            .allocator = self.allocator,
        };
    }

    pub fn detach(self: Tensor) Tensor {
        return self;
    }

    pub fn sum(self: Tensor, dim: usize, keepdim: bool) !Tensor {
        var new_shape = try self.allocator.alloc(usize, if (keepdim) self.shape.len else self.shape.len - 1);
        var idx: usize = 0;
        for (self.shape, 0..) |s, i| {
            if (i != dim) {
                new_shape[idx] = s;
                idx += 1;
            } else if (keepdim) {
                new_shape[idx] = 1;
                idx += 1;
            }
        }
        var result = try Tensor.init(self.allocator, new_shape);
        @memset(result.data, 0.0);
        return result;
    }

    pub fn mean(self: Tensor, dim: usize) !Tensor {
        return try self.sum(dim, false);
    }

    pub fn exp(self: Tensor) !Tensor {
        var result = try Tensor.init(self.allocator, self.shape);
        for (self.data, 0..) |val, i| {
            result.data[i] = @exp(val);
        }
        return result;
    }

    pub fn log(self: Tensor) !Tensor {
        var result = try Tensor.init(self.allocator, self.shape);
        for (self.data, 0..) |val, i| {
            result.data[i] = @log(val + 1e-10);
        }
        return result;
    }

    pub fn add(self: Tensor, other: Tensor) !Tensor {
        var result = try Tensor.init(self.allocator, self.shape);
        for (self.data, 0..) |val, i| {
            result.data[i] = val + other.data[i];
        }
        return result;
    }

    pub fn sub(self: Tensor, other: Tensor) !Tensor {
        var result = try Tensor.init(self.allocator, self.shape);
        for (self.data, 0..) |val, i| {
            result.data[i] = val - other.data[i];
        }
        return result;
    }

    pub fn mul(self: Tensor, scalar: f32) !Tensor {
        var result = try Tensor.init(self.allocator, self.shape);
        for (self.data, 0..) |val, i| {
            result.data[i] = val * scalar;
        }
        return result;
    }

    pub fn pow(self: Tensor, exponent: f32) !Tensor {
        var result = try Tensor.init(self.allocator, self.shape);
        for (self.data, 0..) |val, i| {
            result.data[i] = math.pow(f32, val, exponent);
        }
        return result;
    }

    pub fn matmul(self: Tensor, other: Tensor) !Tensor {
        const m = self.shape[0];
        const n = other.shape[1];
        const k = self.shape[1];
        const result_shape = [_]usize{ m, n };
        var result = try Tensor.init(self.allocator, &result_shape);
        @memset(result.data, 0.0);
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                var sum: f32 = 0.0;
                var l: usize = 0;
                while (l < k) : (l += 1) {
                    sum += self.data[i * k + l] * other.data[l * n + j];
                }
                result.data[i * n + j] = sum;
            }
        }
        return result;
    }

    pub fn transpose(self: Tensor) !Tensor {
        const new_shape = [_]usize{ self.shape[1], self.shape[0] };
        var result = try Tensor.init(self.allocator, &new_shape);
        var i: usize = 0;
        while (i < self.shape[0]) : (i += 1) {
            var j: usize = 0;
            while (j < self.shape[1]) : (j += 1) {
                result.data[j * self.shape[0] + i] = self.data[i * self.shape[1] + j];
            }
        }
        return result;
    }

    pub fn argmin(self: Tensor, dim: i32) !Tensor {
        const new_shape = [_]usize{self.shape[0]};
        var result = try Tensor.init(self.allocator, &new_shape);
        var i: usize = 0;
        while (i < self.shape[0]) : (i += 1) {
            var min_val: f32 = self.data[i * self.shape[1]];
            var min_idx: usize = 0;
            var j: usize = 1;
            while (j < self.shape[1]) : (j += 1) {
                const val = self.data[i * self.shape[1] + j];
                if (val < min_val) {
                    min_val = val;
                    min_idx = j;
                }
            }
            result.data[i] = @floatFromInt(min_idx);
        }
        return result;
    }

    pub fn cdist(a: Tensor, b: Tensor) !Tensor {
        const m = a.shape[0];
        const n = b.shape[0];
        const d = a.shape[1];
        const result_shape = [_]usize{ m, n };
        var result = try Tensor.init(a.allocator, &result_shape);
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                var dist: f32 = 0.0;
                var k: usize = 0;
                while (k < d) : (k += 1) {
                    const diff = a.data[i * d + k] - b.data[j * d + k];
                    dist += diff * diff;
                }
                result.data[i * n + j] = @sqrt(dist);
            }
        }
        return result;
    }

    pub fn indexSelect(self: Tensor, dim: usize, indices: Tensor) !Tensor {
        _ = dim;
        const num_indices = indices.shape[0];
        var result = try Tensor.init(self.allocator, self.shape);
        var i: usize = 0;
        while (i < num_indices) : (i += 1) {
            const idx: usize = @intFromFloat(indices.data[i]);
            @memcpy(result.data[i * self.shape[1] .. (i + 1) * self.shape[1]], self.data[idx * self.shape[1] .. (idx + 1) * self.shape[1]]);
        }
        return result;
    }

    pub fn cat(tensors: []Tensor, dim: i32, allocator: Allocator) !Tensor {
        _ = dim;
        var total_size: usize = 0;
        for (tensors) |t| {
            total_size += t.shape[1];
        }
        const result_shape = [_]usize{ tensors[0].shape[0], total_size };
        var result = try Tensor.init(allocator, &result_shape);
        var offset: usize = 0;
        for (tensors) |t| {
            var i: usize = 0;
            while (i < t.shape[0]) : (i += 1) {
                @memcpy(result.data[i * total_size + offset .. i * total_size + offset + t.shape[1]], t.data[i * t.shape[1] .. (i + 1) * t.shape[1]]);
            }
            offset += t.shape[1];
        }
        return result;
    }

    pub fn permute(self: Tensor, dims: []const usize) !Tensor {
        var new_shape = try self.allocator.alloc(usize, dims.len);
        for (dims, 0..) |d, i| {
            new_shape[i] = self.shape[d];
        }
        var result = try Tensor.init(self.allocator, new_shape);
        if (dims.len == 4 and dims[0] == 0 and dims[1] == 3 and dims[2] == 1 and dims[3] == 2) {
            const b = self.shape[0];
            const h = self.shape[1];
            const w = self.shape[2];
            const c = self.shape[3];
            var bi: usize = 0;
            while (bi < b) : (bi += 1) {
                var hi: usize = 0;
                while (hi < h) : (hi += 1) {
                    var wi: usize = 0;
                    while (wi < w) : (wi += 1) {
                        var ci: usize = 0;
                        while (ci < c) : (ci += 1) {
                            const src_idx = bi * (h * w * c) + hi * (w * c) + wi * c + ci;
                            const dst_idx = bi * (c * h * w) + ci * (h * w) + hi * w + wi;
                            result.data[dst_idx] = self.data[src_idx];
                        }
                    }
                }
            }
        }
        return result;
    }

    pub fn unsqueeze(self: Tensor, dim: i32) !Tensor {
        _ = dim;
        const new_shape = [_]usize{ self.shape[0], 1 };
        return try self.view(&new_shape);
    }

    pub fn clone(self: Tensor) !Tensor {
        var result = try Tensor.init(self.allocator, self.shape);
        @memcpy(result.data, self.data);
        return result;
    }

    pub fn randn(allocator: Allocator, shape: []const usize) !Tensor {
        var tensor = try Tensor.init(allocator, shape);
        var prng = std.rand.DefaultPrng.init(0);
        const random = prng.random();
        for (tensor.data) |*val| {
            val.* = random.floatNorm(f32);
        }
        return tensor;
    }

    pub fn zeros(allocator: Allocator, shape: []const usize) !Tensor {
        var tensor = try Tensor.init(allocator, shape);
        @memset(tensor.data, 0.0);
        return tensor;
    }

    pub fn ones(allocator: Allocator, shape: []const usize) !Tensor {
        var tensor = try Tensor.init(allocator, shape);
        @memset(tensor.data, 1.0);
        return tensor;
    }
};

const Functional = struct {
    pub fn mse_loss(input: Tensor, target: Tensor) !f32 {
        var sum: f32 = 0.0;
        for (input.data, 0..) |val, i| {
            const diff = val - target.data[i];
            sum += diff * diff;
        }
        return sum / @as(f32, @floatFromInt(input.data.len));
    }

    pub fn softmax(input: Tensor, dim: i32) !Tensor {
        _ = dim;
        var result = try Tensor.init(input.allocator, input.shape);
        var max_val: f32 = input.data[0];
        for (input.data) |val| {
            if (val > max_val) max_val = val;
        }
        var sum: f32 = 0.0;
        for (input.data, 0..) |val, i| {
            result.data[i] = @exp(val - max_val);
            sum += result.data[i];
        }
        for (result.data) |*val| {
            val.* /= sum;
        }
        return result;
    }

    pub fn one_hot(indices: Tensor, num_classes: usize, allocator: Allocator) !Tensor {
        const result_shape = [_]usize{ indices.shape[0], num_classes };
        var result = try Tensor.init(allocator, &result_shape);
        @memset(result.data, 0.0);
        for (indices.data, 0..) |idx, i| {
            const class_idx: usize = @intFromFloat(idx);
            result.data[i * num_classes + class_idx] = 1.0;
        }
        return result;
    }

    pub fn relu(input: Tensor) !Tensor {
        var result = try Tensor.init(input.allocator, input.shape);
        for (input.data, 0..) |val, i| {
            result.data[i] = @max(0.0, val);
        }
        return result;
    }

    pub fn tanh(input: Tensor) !Tensor {
        var result = try Tensor.init(input.allocator, input.shape);
        for (input.data, 0..) |val, i| {
            result.data[i] = @tanh(val);
        }
        return result;
    }
};

const Conv2d = struct {
    weight: Tensor,
    bias: ?Tensor,
    kernel_size: usize,
    stride: usize,
    padding: usize,
    in_channels: usize,
    out_channels: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, in_channels: usize, out_channels: usize, kernel_size: usize, stride: usize, padding: usize) !Conv2d {
        const weight_shape = [_]usize{ out_channels, in_channels, kernel_size, kernel_size };
        const weight = try Tensor.randn(allocator, &weight_shape);
        return Conv2d{
            .weight = weight,
            .bias = null,
            .kernel_size = kernel_size,
            .stride = stride,
            .padding = padding,
            .in_channels = in_channels,
            .out_channels = out_channels,
            .allocator = allocator,
        };
    }

    pub fn forward(self: *Conv2d, input: Tensor) !Tensor {
        const batch = input.shape[0];
        const in_h = input.shape[2];
        const in_w = input.shape[3];
        const out_h = (in_h + 2 * self.padding - self.kernel_size) / self.stride + 1;
        const out_w = (in_w + 2 * self.padding - self.kernel_size) / self.stride + 1;
        const output_shape = [_]usize{ batch, self.out_channels, out_h, out_w };
        var output = try Tensor.init(self.allocator, &output_shape);
        @memset(output.data, 0.0);
        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oc: usize = 0;
            while (oc < self.out_channels) : (oc += 1) {
                var oh: usize = 0;
                while (oh < out_h) : (oh += 1) {
                    var ow: usize = 0;
                    while (ow < out_w) : (ow += 1) {
                        var sum: f32 = 0.0;
                        var ic: usize = 0;
                        while (ic < self.in_channels) : (ic += 1) {
                            var kh: usize = 0;
                            while (kh < self.kernel_size) : (kh += 1) {
                                var kw: usize = 0;
                                while (kw < self.kernel_size) : (kw += 1) {
                                    const ih = oh * self.stride + kh;
                                    const iw = ow * self.stride + kw;
                                    if (ih >= self.padding and ih < in_h + self.padding and iw >= self.padding and iw < in_w + self.padding) {
                                        const ih_actual = ih - self.padding;
                                        const iw_actual = iw - self.padding;
                                        const input_idx = b * (self.in_channels * in_h * in_w) + ic * (in_h * in_w) + ih_actual * in_w + iw_actual;
                                        const weight_idx = oc * (self.in_channels * self.kernel_size * self.kernel_size) + ic * (self.kernel_size * self.kernel_size) + kh * self.kernel_size + kw;
                                        sum += input.data[input_idx] * self.weight.data[weight_idx];
                                    }
                                }
                            }
                        }
                        const output_idx = b * (self.out_channels * out_h * out_w) + oc * (out_h * out_w) + oh * out_w + ow;
                        output.data[output_idx] = sum;
                    }
                }
            }
        }
        return output;
    }

    pub fn deinit(self: *Conv2d) void {
        self.weight.deinit();
        if (self.bias) |*b| b.deinit();
    }
};

const ConvTranspose2d = struct {
    weight: Tensor,
    bias: ?Tensor,
    kernel_size: usize,
    stride: usize,
    padding: usize,
    in_channels: usize,
    out_channels: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, in_channels: usize, out_channels: usize, kernel_size: usize, stride: usize, padding: usize) !ConvTranspose2d {
        const weight_shape = [_]usize{ in_channels, out_channels, kernel_size, kernel_size };
        const weight = try Tensor.randn(allocator, &weight_shape);
        return ConvTranspose2d{
            .weight = weight,
            .bias = null,
            .kernel_size = kernel_size,
            .stride = stride,
            .padding = padding,
            .in_channels = in_channels,
            .out_channels = out_channels,
            .allocator = allocator,
        };
    }

    pub fn forward(self: *ConvTranspose2d, input: Tensor) !Tensor {
        const batch = input.shape[0];
        const in_h = input.shape[2];
        const in_w = input.shape[3];
        const out_h = (in_h - 1) * self.stride - 2 * self.padding + self.kernel_size;
        const out_w = (in_w - 1) * self.stride - 2 * self.padding + self.kernel_size;
        const output_shape = [_]usize{ batch, self.out_channels, out_h, out_w };
        var output = try Tensor.init(self.allocator, &output_shape);
        @memset(output.data, 0.0);
        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var ic: usize = 0;
            while (ic < self.in_channels) : (ic += 1) {
                var ih: usize = 0;
                while (ih < in_h) : (ih += 1) {
                    var iw: usize = 0;
                    while (iw < in_w) : (iw += 1) {
                        const input_idx = b * (self.in_channels * in_h * in_w) + ic * (in_h * in_w) + ih * in_w + iw;
                        const input_val = input.data[input_idx];
                        var oc: usize = 0;
                        while (oc < self.out_channels) : (oc += 1) {
                            var kh: usize = 0;
                            while (kh < self.kernel_size) : (kh += 1) {
                                var kw: usize = 0;
                                while (kw < self.kernel_size) : (kw += 1) {
                                    const oh = ih * self.stride + kh;
                                    const ow = iw * self.stride + kw;
                                    if (oh >= self.padding and oh < out_h + self.padding and ow >= self.padding and ow < out_w + self.padding) {
                                        const oh_actual = oh - self.padding;
                                        const ow_actual = ow - self.padding;
                                        if (oh_actual < out_h and ow_actual < out_w) {
                                            const weight_idx = ic * (self.out_channels * self.kernel_size * self.kernel_size) + oc * (self.kernel_size * self.kernel_size) + kh * self.kernel_size + kw;
                                            const output_idx = b * (self.out_channels * out_h * out_w) + oc * (out_h * out_w) + oh_actual * out_w + ow_actual;
                                            output.data[output_idx] += input_val * self.weight.data[weight_idx];
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        return output;
    }

    pub fn deinit(self: *ConvTranspose2d) void {
        self.weight.deinit();
        if (self.bias) |*b| b.deinit();
    }
};

const BatchNorm2d = struct {
    num_features: usize,
    weight: Tensor,
    bias: Tensor,
    running_mean: Tensor,
    running_var: Tensor,
    epsilon: f32,
    momentum: f32,
    allocator: Allocator,

    pub fn init(allocator: Allocator, num_features: usize) !BatchNorm2d {
        const shape = [_]usize{num_features};
        const weight = try Tensor.ones(allocator, &shape);
        const bias = try Tensor.zeros(allocator, &shape);
        const running_mean = try Tensor.zeros(allocator, &shape);
        const running_var = try Tensor.ones(allocator, &shape);
        return BatchNorm2d{
            .num_features = num_features,
            .weight = weight,
            .bias = bias,
            .running_mean = running_mean,
            .running_var = running_var,
            .epsilon = 1e-5,
            .momentum = 0.1,
            .allocator = allocator,
        };
    }

    pub fn forward(self: *BatchNorm2d, input: Tensor) !Tensor {
        var output = try Tensor.init(self.allocator, input.shape);
        const batch = input.shape[0];
        const channels = input.shape[1];
        const height = input.shape[2];
        const width = input.shape[3];
        var c: usize = 0;
        while (c < channels) : (c += 1) {
            var mean: f32 = 0.0;
            var count: usize = 0;
            var b: usize = 0;
            while (b < batch) : (b += 1) {
                var h: usize = 0;
                while (h < height) : (h += 1) {
                    var w: usize = 0;
                    while (w < width) : (w += 1) {
                        const idx = b * (channels * height * width) + c * (height * width) + h * width + w;
                        mean += input.data[idx];
                        count += 1;
                    }
                }
            }
            mean /= @as(f32, @floatFromInt(count));
            var variance: f32 = 0.0;
            b = 0;
            while (b < batch) : (b += 1) {
                var h: usize = 0;
                while (h < height) : (h += 1) {
                    var w: usize = 0;
                    while (w < width) : (w += 1) {
                        const idx = b * (channels * height * width) + c * (height * width) + h * width + w;
                        const diff = input.data[idx] - mean;
                        variance += diff * diff;
                    }
                }
            }
            variance /= @as(f32, @floatFromInt(count));
            const std_dev = @sqrt(variance + self.epsilon);
            b = 0;
            while (b < batch) : (b += 1) {
                var h: usize = 0;
                while (h < height) : (h += 1) {
                    var w: usize = 0;
                    while (w < width) : (w += 1) {
                        const idx = b * (channels * height * width) + c * (height * width) + h * width + w;
                        const normalized = (input.data[idx] - mean) / std_dev;
                        output.data[idx] = normalized * self.weight.data[c] + self.bias.data[c];
                    }
                }
            }
        }
        return output;
    }

    pub fn deinit(self: *BatchNorm2d) void {
        self.weight.deinit();
        self.bias.deinit();
        self.running_mean.deinit();
        self.running_var.deinit();
    }
};

const Embedding = struct {
