    pub fn forward(self: *Embedding, indices: Tensor) !Tensor {
        const num_indices = indices.shape[0];
        const result_shape = [_]usize{ num_indices, self.embedding_dim };
        var result = try Tensor.init(self.allocator, &result_shape);
        var i: usize = 0;
        while (i < num_indices) : (i += 1) {
            const idx: usize = @intFromFloat(indices.data[i]);
            @memcpy(result.data[i * self.embedding_dim .. (i + 1) * self.embedding_dim], self.weight.data[idx * self.embedding_dim .. (idx + 1) * self.embedding_dim]);
