const SemanticSubspaceQuantization = struct {
    num_embeddings: usize,
    embedding_dim: usize,
    num_subspaces: usize,
    subspace_dim: usize,
    embedding: Embedding,
    subspace_embeddings: ArrayList(Embedding),
    weight: Parameter,
    allocator: Allocator,

    pub fn init(allocator: Allocator, num_embeddings: usize, embedding_dim: usize, num_subspaces: usize) !SemanticSubspaceQuantization {
        const subspace_dim = embedding_dim / num_subspaces;
        if (embedding_dim % num_subspaces != 0) {
            return error.InvalidDimensions;
        }
        const embedding = try Embedding.init(allocator, num_embeddings, embedding_dim);
        var subspace_embeddings = ArrayList(Embedding).init(allocator);
        var i: usize = 0;
        while (i < num_subspaces) : (i += 1) {
            const sub_emb = try Embedding.init(allocator, num_embeddings, subspace_dim);
            try subspace_embeddings.append(sub_emb);
        }
        const weight_shape = [_]usize{num_subspaces};
        const weight_data = try Tensor.ones(allocator, &weight_shape);
        const weight = Parameter.init(weight_data);
        return SemanticSubspaceQuantization{
            .num_embeddings = num_embeddings,
            .embedding_dim = embedding_dim,
            .num_subspaces = num_subspaces,
            .subspace_dim = subspace_dim,
            .embedding = embedding,
            .subspace_embeddings = subspace_embeddings,
            .weight = weight,
            .allocator = allocator,
        };
    }

    pub fn forward(self: *SemanticSubspaceQuantization, z_e: Tensor) !struct { Tensor, f32, Tensor } {
        const flat_shape = [_]usize{ z_e.data.len / self.embedding_dim, self.embedding_dim };
        var z_e_flat = try z_e.view(&flat_shape);
        const distances = try Tensor.cdist(z_e_flat.detach(), self.embedding.weight);
        const indices = try distances.argmin(-1);
        var z_q_main = try self.embedding.forward(indices);
        const z_e_shape_copy = try self.allocator.dupe(usize, z_e.shape);
        z_q_main.shape = z_e_shape_copy;
        var z_q_subspaces_list = ArrayList(Tensor).init(self.allocator);
        defer z_q_subspaces_list.deinit();
        var i: usize = 0;
        while (i < self.num_subspaces) : (i += 1) {
            const start = i * self.subspace_dim;
            const end = (i + 1) * self.subspace_dim;
            var sub_z_e_data = try self.allocator.alloc(f32, z_e_flat.shape[0] * self.subspace_dim);
            var row: usize = 0;
            while (row < z_e_flat.shape[0]) : (row += 1) {
                @memcpy(sub_z_e_data[row * self.subspace_dim .. (row + 1) * self.subspace_dim], z_e_flat.data[row * self.embedding_dim + start .. row * self.embedding_dim + end]);
            }
            const sub_z_e_shape = [_]usize{ z_e_flat.shape[0], self.subspace_dim };
            var sub_z_e = Tensor{
                .data = sub_z_e_data,
                .shape = try self.allocator.dupe(usize, &sub_z_e_shape),
                .allocator = self.allocator,
            };
            const sub_distances = try Tensor.cdist(sub_z_e.detach(), self.subspace_embeddings.items[i].weight);
            const sub_indices = try sub_distances.argmin(-1);
            const z_q_sub = try self.subspace_embeddings.items[i].forward(sub_indices);
            try z_q_subspaces_list.append(z_q_sub);
            sub_z_e.deinit();
            sub_distances.deinit();
        }
        const z_q_subspaces = try Tensor.cat(z_q_subspaces_list.items, -1, self.allocator);
        const weights = try Functional.softmax(self.weight.data, 0);
        const weights_view_shape = [_]usize{ 1, self.num_subspaces };
        var weights_view = try weights.view(&weights_view_shape);
        var z_q_combined_sum: f32 = 0.0;
        i = 0;
        while (i < z_q_subspaces.data.len) : (i += 1) {
            const subspace_idx = (i / self.subspace_dim) % self.num_subspaces;
            z_q_combined_sum += z_q_subspaces.data[i] * weights.data[subspace_idx];
        }
        const z_q_combined_shape = try self.allocator.dupe(usize, z_e.shape);
        var z_q_combined = Tensor{
            .data = try self.allocator.alloc(f32, z_e.data.len),
            .shape = z_q_combined_shape,
            .allocator = self.allocator,
        };
        @memset(z_q_combined.data, z_q_combined_sum / @as(f32, @floatFromInt(z_q_subspaces.data.len)));
        var z_q = try Tensor.init(self.allocator, z_e.shape);
        for (z_q.data, 0..) |*val, idx| {
            val.* = z_q_main.data[idx] + 0.1 * z_q_combined.data[idx];
        }
        const z_e_detached = z_e.detach();
        const z_q_detached = z_q.detach();
        const commitment_loss = try Functional.mse_loss(z_q, z_e_detached);
        const codebook_loss = try Functional.mse_loss(z_e, z_q_detached);
        const loss = commitment_loss + codebook_loss;
        for (z_q.data, 0..) |*val, idx| {
            val.* = z_e.data[idx] + (z_q.data[idx] - z_e.data[idx]);
        }
        weights.deinit();
        weights_view.deinit();
        z_q_combined.deinit();
        z_q_subspaces.deinit();
        distances.deinit();
        return .{ z_q, loss, indices };
    }

    pub fn deinit(self: *SemanticSubspaceQuantization) void {
        self.embedding.deinit();
        for (self.subspace_embeddings.items) |*emb| {
            emb.deinit();
        }
        self.subspace_embeddings.deinit();
        self.weight.deinit();
    }
};

const VectorQuantizerEMA = struct {
    embedding_dim: usize,
    num_embeddings: usize,
    commitment_cost: f32,
    decay: f32,
    epsilon: f32,
    embedding: Tensor,
    cluster_size: Tensor,
    embed_avg: Tensor,
    training: bool,
    allocator: Allocator,

    pub fn init(allocator: Allocator, num_embeddings: usize, embedding_dim: usize, commitment_cost: f32, decay: f32, epsilon: f32) !VectorQuantizerEMA {
        const shape = [_]usize{ num_embeddings, embedding_dim };
        const embedding = try Tensor.randn(allocator, &shape);
        const cluster_size_shape = [_]usize{num_embeddings};
        const cluster_size = try Tensor.zeros(allocator, &cluster_size_shape);
        const embed_avg = try embedding.clone();
        return VectorQuantizerEMA{
            .embedding_dim = embedding_dim,
            .num_embeddings = num_embeddings,
            .commitment_cost = commitment_cost,
            .decay = decay,
            .epsilon = epsilon,
            .embedding = embedding,
            .cluster_size = cluster_size,
            .embed_avg = embed_avg,
            .training = true,
            .allocator = allocator,
        };
    }

    pub fn forward(self: *VectorQuantizerEMA, inputs: Tensor) !struct { f32, Tensor, f32, Tensor } {
        const input_shape = inputs.shape;
        const flat_shape = [_]usize{ inputs.data.len / self.embedding_dim, self.embedding_dim };
        var flat_input = try inputs.view(&flat_shape);
        const flat_input_sq = try flat_input.pow(2);
        const flat_input_sum = try flat_input_sq.sum(1, true);
        const embedding_sq = try self.embedding.pow(2);
        const embedding_sum = try embedding_sq.sum(1, false);
        const flat_input_t = try flat_input.transpose();
        const matmul_result = try self.embedding.matmul(flat_input_t);
        const matmul_result_t = try matmul_result.transpose();
        var distances = try Tensor.init(self.allocator, &[_]usize{ flat_input.shape[0], self.embedding.shape[0] });
        var i: usize = 0;
        while (i < flat_input.shape[0]) : (i += 1) {
            var j: usize = 0;
            while (j < self.embedding.shape[0]) : (j += 1) {
                distances.data[i * self.embedding.shape[0] + j] = flat_input_sum.data[i] + embedding_sum.data[j] - 2 * matmul_result_t.data[i * self.embedding.shape[0] + j];
            }
        }
        const encoding_indices = try distances.argmin(1);
        var quantized = try self.embedding.indexSelect(0, encoding_indices);
        const quantized_shape = try self.allocator.dupe(usize, input_shape);
        quantized.shape = quantized_shape;
        if (self.training) {
            const encodings = try Functional.one_hot(encoding_indices, self.num_embeddings, self.allocator);
            const encodings_sum = try encodings.sum(0, false);
            for (self.cluster_size.data, 0..) |*val, idx| {
                val.* = val.* * self.decay + (1 - self.decay) * encodings_sum.data[idx];
            }
            const encodings_t = try encodings.transpose();
            const dw = try encodings_t.matmul(flat_input);
            for (self.embed_avg.data, 0..) |*val, idx| {
                val.* = val.* * self.decay + (1 - self.decay) * dw.data[idx];
            }
            var n: f32 = 0.0;
            for (self.cluster_size.data) |val| {
                n += val;
            }
            for (self.cluster_size.data) |*val| {
                val.* = (val.* + self.epsilon) / (n + @as(f32, @floatFromInt(self.num_embeddings)) * self.epsilon) * n;
            }
            for (self.embedding.data, 0..) |*val, idx| {
                const row = idx / self.embedding_dim;
                val.* = self.embed_avg.data[idx] / self.cluster_size.data[row];
            }
            encodings.deinit();
            encodings_sum.deinit();
            encodings_t.deinit();
            dw.deinit();
        }
        const quantized_detached = quantized.detach();
        const inputs_detached = inputs.detach();
        const e_latent_loss = try Functional.mse_loss(quantized_detached, inputs);
        const q_latent_loss = try Functional.mse_loss(quantized, inputs_detached);
        const loss = q_latent_loss + self.commitment_cost * e_latent_loss;
        for (quantized.data, 0..) |*val, idx| {
            val.* = inputs.data[idx] + (quantized.data[idx] - inputs.data[idx]);
        }
        const encodings_for_probs = try Functional.one_hot(encoding_indices, self.num_embeddings, self.allocator);
        const avg_probs = try encodings_for_probs.mean(0);
        const log_probs = try avg_probs.log();
        var entropy_sum: f32 = 0.0;
        for (avg_probs.data, 0..) |prob, idx| {
            entropy_sum += prob * log_probs.data[idx];
        }
        const perplexity = @exp(-entropy_sum);
        flat_input_sq.deinit();
        flat_input_sum.deinit();
        embedding_sq.deinit();
        embedding_sum.deinit();
        flat_input_t.deinit();
        matmul_result.deinit();
        matmul_result_t.deinit();
        distances.deinit();
        encodings_for_probs.deinit();
        avg_probs.deinit();
        log_probs.deinit();
        return .{ loss, quantized, perplexity, encoding_indices };
    }

    pub fn deinit(self: *VectorQuantizerEMA) void {
        self.embedding.deinit();
        self.cluster_size.deinit();
        self.embed_avg.deinit();
    }
};

const ResidualBlock = struct {
    conv1: Conv2d,
    bn1: BatchNorm2d,
    conv2: Conv2d,
    bn2: BatchNorm2d,
    shortcut: ?struct { conv: Conv2d, bn: BatchNorm2d },
    allocator: Allocator,

    pub fn init(allocator: Allocator, in_channels: usize, out_channels: usize) !ResidualBlock {
        const conv1 = try Conv2d.init(allocator, in_channels, out_channels, 3, 1, 1);
        const bn1 = try BatchNorm2d.init(allocator, out_channels);
        const conv2 = try Conv2d.init(allocator, out_channels, out_channels, 3, 1, 1);
        const bn2 = try BatchNorm2d.init(allocator, out_channels);
        var shortcut: ?struct { conv: Conv2d, bn: BatchNorm2d } = null;
        if (in_channels != out_channels) {
            const sc_conv = try Conv2d.init(allocator, in_channels, out_channels, 1, 1, 0);
            const sc_bn = try BatchNorm2d.init(allocator, out_channels);
            shortcut = .{ .conv = sc_conv, .bn = sc_bn };
        }
        return ResidualBlock{
            .conv1 = conv1,
            .bn1 = bn1,
            .conv2 = conv2,
            .bn2 = bn2,
            .shortcut = shortcut,
            .allocator = allocator,
        };
    }

    pub fn forward(self: *ResidualBlock, x: Tensor) !Tensor {
        var residual = x;
        var out = try self.conv1.forward(x);
        var out_bn1 = try self.bn1.forward(out);
        out.deinit();
        var out_relu1 = try Functional.relu(out_bn1);
        out_bn1.deinit();
        var out_conv2 = try self.conv2.forward(out_relu1);
        out_relu1.deinit();
        var out_bn2 = try self.bn2.forward(out_conv2);
        out_conv2.deinit();
        if (self.shortcut) |*sc| {
            var sc_conv = try sc.conv.forward(residual);
            var sc_bn = try sc.bn.forward(sc_conv);
            sc_conv.deinit();
            residual = sc_bn;
        }
        var result = try Tensor.init(self.allocator, out_bn2.shape);
        for (result.data, 0..) |*val, i| {
            val.* = out_bn2.data[i] + residual.data[i];
        }
        out_bn2.deinit();
        if (self.shortcut != null) {
            residual.deinit();
        }
        var final_result = try Functional.relu(result);
        result.deinit();
        return final_result;
    }

    pub fn deinit(self: *ResidualBlock) void {
        self.conv1.deinit();
        self.bn1.deinit();
        self.conv2.deinit();
        self.bn2.deinit();
        if (self.shortcut) |*sc| {
            sc.conv.deinit();
            sc.bn.deinit();
        }
    }
};

const Sequential = struct {
    layers: ArrayList(*anyopaque),
    layer_types: ArrayList(LayerType),
    allocator: Allocator,

    const LayerType = enum {
        Conv2d,
        ReLU,
        ConvTranspose2d,
        Tanh,
        ResidualBlock,
    };

    pub fn init(allocator: Allocator) Sequential {
        return Sequential{
            .layers = ArrayList(*anyopaque).init(allocator),
            .layer_types = ArrayList(LayerType).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn add(self: *Sequential, layer: anytype, layer_type: LayerType) !void {
        const ptr = try self.allocator.create(@TypeOf(layer));
        ptr.* = layer;
        try self.layers.append(ptr);
        try self.layer_types.append(layer_type);
    }

    pub fn forward(self: *Sequential, input: Tensor) !Tensor {
        var current = input;
        for (self.layers.items, 0..) |layer, i| {
            const prev = current;
            const layer_type = self.layer_types.items[i];
            current = switch (layer_type) {
                .Conv2d => blk: {
                    const conv: *Conv2d = @ptrCast(@alignCast(layer));
                    break :blk try conv.forward(prev);
                },
                .ReLU => try Functional.relu(prev),
                .ConvTranspose2d => blk: {
                    const convt: *ConvTranspose2d = @ptrCast(@alignCast(layer));
                    break :blk try convt.forward(prev);
                },
                .Tanh => try Functional.tanh(prev),
                .ResidualBlock => blk: {
                    const rb: *ResidualBlock = @ptrCast(@alignCast(layer));
                    break :blk try rb.forward(prev);
                },
            };
            if (i > 0) {
                prev.deinit();
            }
        }
        return current;
    }

    pub fn deinit(self: *Sequential) void {
        for (self.layers.items, 0..) |layer, i| {
            const layer_type = self.layer_types.items[i];
            switch (layer_type) {
                .Conv2d => {
                    const conv: *Conv2d = @ptrCast(@alignCast(layer));
                    conv.deinit();
                    self.allocator.destroy(conv);
                },
                .ReLU => {},
                .ConvTranspose2d => {
                    const convt: *ConvTranspose2d = @ptrCast(@alignCast(layer));
                    convt.deinit();
                    self.allocator.destroy(convt);
                },
                .Tanh => {},
                .ResidualBlock => {
                    const rb: *ResidualBlock = @ptrCast(@alignCast(layer));
                    rb.deinit();
                    self.allocator.destroy(rb);
                },
            }
        }
        self.layers.deinit();
        self.layer_types.deinit();
    }
};

const VQVAE = struct {
    encoder: Sequential,
    pre_vq_conv: Conv2d,
    vq_layer: SemanticSubspaceQuantization,
    decoder: Sequential,
    allocator: Allocator,

    pub fn init(allocator: Allocator, in_channels: usize, hidden_channels: usize, num_res_blocks: usize, embedding_dim: usize, num_embeddings: usize) !VQVAE {
        var encoder = Sequential.init(allocator);
        const conv1 = try Conv2d.init(allocator, in_channels, hidden_channels / 2, 4, 2, 1);
        try encoder.add(conv1, Sequential.LayerType.Conv2d);
        try encoder.add({}, Sequential.LayerType.ReLU);
        const conv2 = try Conv2d.init(allocator, hidden_channels / 2, hidden_channels, 4, 2, 1);
        try encoder.add(conv2, Sequential.LayerType.Conv2d);
        try encoder.add({}, Sequential.LayerType.ReLU);
        var i: usize = 0;
        while (i < num_res_blocks) : (i += 1) {
            const rb = try ResidualBlock.init(allocator, hidden_channels, hidden_channels);
            try encoder.add(rb, Sequential.LayerType.ResidualBlock);
        }
        const conv3 = try Conv2d.init(allocator, hidden_channels, hidden_channels, 3, 1, 1);
        try encoder.add(conv3, Sequential.LayerType.Conv2d);
        const pre_vq_conv = try Conv2d.init(allocator, hidden_channels, embedding_dim, 1, 1, 0);
        const vq_layer = try SemanticSubspaceQuantization.init(allocator, num_embeddings, embedding_dim, 4);
        var decoder = Sequential.init(allocator);
        const dec_conv1 = try Conv2d.init(allocator, embedding_dim, hidden_channels, 3, 1, 1);
        try decoder.add(dec_conv1, Sequential.LayerType.Conv2d);
        try decoder.add({}, Sequential.LayerType.ReLU);
        i = 0;
        while (i < num_res_blocks) : (i += 1) {
            const rb = try ResidualBlock.init(allocator, hidden_channels, hidden_channels);
            try decoder.add(rb, Sequential.LayerType.ResidualBlock);
        }
        const dec_convt1 = try ConvTranspose2d.init(allocator, hidden_channels, hidden_channels / 2, 4, 2, 1);
        try decoder.add(dec_convt1, Sequential.LayerType.ConvTranspose2d);
        try decoder.add({}, Sequential.LayerType.ReLU);
        const dec_convt2 = try ConvTranspose2d.init(allocator, hidden_channels / 2, in_channels, 4, 2, 1);
        try decoder.add(dec_convt2, Sequential.LayerType.ConvTranspose2d);
        try decoder.add({}, Sequential.LayerType.Tanh);
        return VQVAE{
            .encoder = encoder,
            .pre_vq_conv = pre_vq_conv,
            .vq_layer = vq_layer,
            .decoder = decoder,
            .allocator = allocator,
        };
    }

    pub fn forward(self: *VQVAE, x: Tensor) !struct { Tensor, f32, Tensor } {
        var z_e = try self.encoder.forward(x);
        var z_e_pre = try self.pre_vq_conv.forward(z_e);
        z_e.deinit();
        const vq_result = try self.vq_layer.forward(z_e_pre);
        const z_q = vq_result[0];
        const vq_loss = vq_result[1];
        const indices = vq_result[2];
        z_e_pre.deinit();
        var x_recon = try self.decoder.forward(z_q);
        return .{ x_recon, vq_loss, indices };
    }

    pub fn encode(self: *VQVAE, x: Tensor) !Tensor {
        var z_e = try self.encoder.forward(x);
        var z_e_pre = try self.pre_vq_conv.forward(z_e);
        z_e.deinit();
        const vq_result = try self.vq_layer.forward(z_e_pre);
        z_e_pre.deinit();
        vq_result[0].deinit();
        return vq_result[2];
    }

    pub fn decode(self: *VQVAE, indices: Tensor) !Tensor {
        var z_q = try self.vq_layer.embedding.forward(indices);
        const perm_dims = [_]usize{ 0, 3, 1, 2 };
        var z_q_perm = try z_q.permute(&perm_dims);
        z_q.deinit();
        var x_recon = try self.decoder.forward(z_q_perm);
        z_q_perm.deinit();
        return x_recon;
    }

    pub fn deinit(self: *VQVAE) void {
        self.encoder.deinit();
        self.pre_vq_conv.deinit();
        self.vq_layer.deinit();
        self.decoder.deinit();
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    var vqvae = try VQVAE.init(allocator, 3, 128, 2, 256, 1024);
    defer vqvae.deinit();
    const input_shape = [_]usize{ 1, 3, 64, 64 };
    var input = try Tensor.randn(allocator, &input_shape);
    defer input.deinit();
    const result = try vqvae.forward(input);
    var x_recon = result[0];
    const vq_loss = result[1];
    var indices = result[2];
    defer x_recon.deinit();
    defer indices.deinit();
    std.debug.print("VQ Loss: {}\n", .{vq_loss});
}
